document.compatMode
// 'CSS1Compat' = standards mode
// 'BackCompat'  = quirks mode

if ('serviceWorker' in navigator) {
  navigator.serviceWorker.register('/sw.js')
}

const form  = document.querySelector('form')
const email = form.elements.email

email.addEventListener('input', () => {
  if (email.validity.typeMismatch) {
    email.setCustomValidity('Email chưa đúng định dạng, ví dụ: ban@congty.vn')
  } else if (email.validity.valueMissing) {
    email.setCustomValidity('Vui lòng nhập email')
  } else {
    email.setCustomValidity('')      // chuỗi rỗng = hợp lệ
  }
})

form.addEventListener('submit', (e) => {
  if (!form.checkValidity()) {       // kiểm tra, KHÔNG hiện bong bóng lỗi
    e.preventDefault()
    form.reportValidity()            // kiểm tra VÀ hiện bong bóng + focus
  }
})

const form = document.querySelector('form')

form.addEventListener('submit', async (e) => {
  e.preventDefault()
  const fd = new FormData(form)      // lấy mọi field có thuộc tính name

  fd.append('source', 'web')         // thêm field ngoài form
  fd.get('email')                    // đọc một giá trị
  fd.getAll('tags')                  // nhiều giá trị cùng tên (checkbox)

  await fetch('/api/profile', { method: 'POST', body: fd })
  // KHÔNG set Content-Type — browser tự sinh boundary cho multipart
})

/* SAI: xoá hẳn dấu focus */
:focus { outline: none; }

/* ĐÚNG: chỉ hiện khi điều hướng bằng bàn phím, và vẫn thấy rõ */
:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

function focusItem(items, next) {
  items.forEach((el, i) => { el.tabIndex = i === next ? 0 : -1 })
  items[next].focus()
}

.card { transition: transform .3s ease; }

@media (prefers-reduced-motion: reduce) {
  .card { transition: opacity .15s ease; transform: none; }
}

const mq = window.matchMedia('(prefers-reduced-motion: reduce)')
if (mq.matches) drawStaticFrame()
else startLoop()

